package com.tencent.weknora.security;
import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.*;import com.fasterxml.jackson.databind.ObjectMapper;import static org.junit.jupiter.api.Assertions.*;
class PublicAuthRateLimiterTest {
    @TestFactory java.util.stream.Stream<DynamicTest> actualGinTrustedProxyClientIP()throws Exception{var json=new ObjectMapper();var rows=json.readTree(java.nio.file.Files.readString(java.nio.file.Path.of("src/test/java/com/tencent/weknora/security/public-auth-ip-golden.json")));java.util.List<DynamicTest> tests=new java.util.ArrayList<>();for(var row:rows)tests.add(DynamicTest.dynamicTest(row.path("name").asText(),()->{String proxies=null;if(!row.path("proxies").isNull()){java.util.List<String> values=new java.util.ArrayList<>();row.path("proxies").forEach(v->values.add(v.asText()));proxies=String.join(",",values);}var limiter=new PublicAuthRateLimiter(proxies,()->0L);var request=new MockHttpServletRequest();request.setRemoteAddr(row.path("remote").asText());row.path("xff").forEach(v->request.addHeader("X-Forwarded-For",v.asText()));row.path("real").forEach(v->request.addHeader("X-Real-IP",v.asText()));assertEquals(row.path("body").path("ip").asText(),limiter.clientIP(request));}));return tests.stream();}

    @Test void slidingWindowRejectedRequestsDoNotExtendCutoff(){AtomicLong time=new AtomicLong();var l=new PublicAuthRateLimiter(null,time::get);for(int i=0;i<30;i++)assertTrue(l.allow("ip"));assertFalse(l.allow("ip"));time.set(59_999_999_999L);assertFalse(l.allow("ip"));time.set(60_000_000_000L);assertTrue(l.allow("ip"));assertTrue(l.allow("other"));}
    @Test void concurrentAdmissionNeverExceedsThirty()throws Exception{var limiter=new PublicAuthRateLimiter("",()->0L);AtomicInteger accepted=new AtomicInteger();try(var executor=Executors.newFixedThreadPool(12)){for(int i=0;i<120;i++)executor.submit(()->{if(limiter.allow("same"))accepted.incrementAndGet();});executor.shutdown();assertTrue(executor.awaitTermination(10,TimeUnit.SECONDS));}assertEquals(30,accepted.get());}
    @Test void emptyClientAddressSharesUnknownBucket(){var limiter=new PublicAuthRateLimiter("",()->0L);for(int i=0;i<30;i++)assertTrue(limiter.allow(""));assertFalse(limiter.allow(null));}
    @Test void failedLookupAndRegistrationShareProcessBudgetAndOtherMethodsRemainUnrestricted()throws Exception{var limiter=new PublicAuthRateLimiter("",()->0L);var filter=new PublicAuthRateLimitFilter(limiter,new ObjectMapper());AtomicInteger called=new AtomicInteger();for(int i=0;i<31;i++){var request=new MockHttpServletRequest("POST",i%2==0?"/api/v1/auth/invitations/lookup":"/api/v1/auth/register-by-invite");request.setRemoteAddr("203.0.113.4");var response=new MockHttpServletResponse();filter.doFilter(request,response,(q,s)->{called.incrementAndGet();((jakarta.servlet.http.HttpServletResponse)s).setStatus(400);});assertEquals(i<30?400:429,response.getStatus());if(i==30){var body=new ObjectMapper().readTree(response.getContentAsString());assertEquals(1006,body.path("error").path("code").asInt());assertTrue(body.path("error").path("details").isNull());}}assertEquals(30,called.get());var get=new MockHttpServletRequest("GET","/api/v1/auth/invitations/lookup");var response=new MockHttpServletResponse();filter.doFilter(get,response,(q,s)->called.incrementAndGet());assertEquals(31,called.get());}
}
